import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';
class MainShell extends StatelessWidget{const MainShell({required this.navigationShell,super.key});final StatefulNavigationShell navigationShell;@override Widget build(BuildContext context)=>Scaffold(body:navigationShell,bottomNavigationBar:NavigationBar(selectedIndex:navigationShell.currentIndex,onDestinationSelected:(i)=>navigationShell.goBranch(i,initialLocation:i==navigationShell.currentIndex),destinations:const [NavigationDestination(icon:Icon(Icons.today),label:'Сегодня'),NavigationDestination(icon:Icon(Icons.route),label:'План'),NavigationDestination(icon:Icon(Icons.credit_card),label:'Долги'),NavigationDestination(icon:Icon(Icons.receipt_long),label:'Операции'),NavigationDestination(icon:Icon(Icons.person),label:'Профиль')]));}
